import{_ as p,r as a,o,c,e as s,a as l,s as i}from"./chunks/framework.CXcwiNg-.js";const v=JSON.parse('{"title":"Collection - October CMS - 3.x","titleTemplate":false,"description":"Добавление коллекции записей модели на страницу.","frontmatter":{"subtitle":"Добавление коллекции записей модели на страницу."},"headers":[{"level":2,"title":"Доступные свойства","slug":"доступные-своиства","link":"#доступные-своиства","children":[]},{"level":2,"title":"Базовое использование","slug":"базовое-использование","link":"#базовое-использование","children":[]},{"level":2,"title":"Выполнение запросов","slug":"выполнение-запросов","link":"#выполнение-запросов","children":[{"level":3,"title":"Доступ к типу записи","slug":"доступ-к-типу-записи","link":"#доступ-к-типу-записи","children":[]},{"level":3,"title":"Пагинация записей","slug":"пагинация-записеи","link":"#пагинация-записеи","children":[]},{"level":3,"title":"Поиск записей","slug":"поиск-записеи","link":"#поиск-записеи","children":[]}]},{"level":2,"title":"Жадная загрузка связанных записей","slug":"жадная-загрузка-связанных-записеи","link":"#жадная-загрузка-связанных-записеи","children":[]},{"level":2,"title":"Подсчёт записей","slug":"подсчет-записеи","link":"#подсчет-записеи","children":[{"level":4,"title":"См. также","slug":"см-также","link":"#см-также","children":[]}]}],"relativePath":"3.x/ru/cms/components/collection.md","filePath":"3.x/ru/cms/components/collection.md"}'),u={name:"3.x/ru/cms/components/collection.md"};function r(g,n,k,d,h,m){const t=a("pre-heading"),e=a("post-heading");return o(),c("div",null,[s(t),n[0]||(n[0]=l("h1",null,"Collection",-1)),s(e),n[1]||(n[1]=i(`<p>Компонент <code>collection</code> отображает коллекцию записей на странице. Компонент collection может использоваться на любой странице, макете или фрагменте.</p><h2 id="доступные-своиства"><a href="#доступные-своиства" class="header-anchor">#</a> Доступные свойства</h2><p>Компонент поддерживает следующие свойства.</p><div class="table"><table tabindex="0"><thead><tr><th>Свойство</th><th>Описание</th></tr></thead><tbody><tr><td><strong>handle</strong></td><td>Handle <a href="./../tailor/blueprints.html">чертежа записи</a>.</td></tr><tr><td><strong>recordsPerPage</strong></td><td>Количество записей для отображения на одной странице. Оставьте пустым для отключения пагинации.</td></tr><tr><td><strong>pageNumber</strong></td><td>Это значение используется для определения текущей страницы пользователя.</td></tr><tr><td><strong>sortColumn</strong></td><td>Имя столбца для сортировки записей.</td></tr><tr><td><strong>sortDirection</strong></td><td>Направление сортировки записей. Поддерживаемые значения: <code>asc</code> и <code>desc</code>.</td></tr></tbody></table></div><h2 id="базовое-использование"><a href="#базовое-использование" class="header-anchor">#</a> Базовое использование</h2><p>Следующий пример добавляет коллекцию записей <strong>Blog\\Post</strong> на страницу. Коллекция доступна в Twig через перебор стандартной переменной <code>collection</code>.</p><div class="custom-block cmstemplate"><div class="language-ini extra-class"><pre class="language-ini"><code><span class="token section"><span class="token punctuation">[</span><span class="token section-name selector">collection</span><span class="token punctuation">]</span></span>
<span class="token key attr-name">handle</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;<span class="token inner-value">Blog\\Post</span>&quot;</span>
</code></pre></div><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">for</span> post <span class="token operator">in</span> collection <span class="token delimiter punctuation">%}</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>h1</span><span class="token punctuation">&gt;</span></span><span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> post<span class="token punctuation">.</span>title <span class="token delimiter punctuation">}}</span></span><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>h1</span><span class="token punctuation">&gt;</span></span>
<span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">endfor</span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div></div><p>Когда на одной странице используется несколько коллекций, компоненту можно назначить имя <strong>posts</strong> с помощью псевдонима, и это имя переменной становится доступным на странице. Следующая коллекция доступна через переменную <code>posts</code>.</p><div class="custom-block cmstemplate"><div class="language-ini extra-class"><pre class="language-ini"><code><span class="token section"><span class="token punctuation">[</span><span class="token section-name selector">collection posts</span><span class="token punctuation">]</span></span>
<span class="token key attr-name">handle</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;<span class="token inner-value">Blog\\Post</span>&quot;</span>
</code></pre></div><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">for</span> post <span class="token operator">in</span> posts <span class="token delimiter punctuation">%}</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>h1</span><span class="token punctuation">&gt;</span></span><span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> post<span class="token punctuation">.</span>title <span class="token delimiter punctuation">}}</span></span><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>h1</span><span class="token punctuation">&gt;</span></span>
<span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">endfor</span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div></div><p>Используйте выражение <code>is empty</code> или <code>is not empty</code> для проверки наличия хотя бы одной записи в коллекции.</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">if</span> posts <span class="token operator">is</span> <span class="token operator">not</span> empty <span class="token delimiter punctuation">%}</span></span>
    <span class="token twig language-twig"><span class="token comment">{# ... #}</span></span>
<span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">endif</span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><h2 id="выполнение-запросов"><a href="#выполнение-запросов" class="header-anchor">#</a> Выполнение запросов</h2><p>При обращении к переменной компонента через метод она переключается на <a href="./../../extend/database/query.html">запрос к модели базы данных</a>. Например, чтобы показать только записи с полем <code>color</code> со значением <strong>blue</strong>, используйте метод запроса <code>where</code>. Тег <code>{% set %}</code> присвоит результат новой переменной.</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">set</span> bluePosts <span class="token operator">=</span> posts<span class="token punctuation">.</span>where<span class="token punctuation">(</span><span class="token string"><span class="token punctuation">&#39;</span>color<span class="token punctuation">&#39;</span></span><span class="token punctuation">,</span> <span class="token string"><span class="token punctuation">&#39;</span>blue<span class="token punctuation">&#39;</span></span><span class="token punctuation">)</span><span class="token punctuation">.</span>get<span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><p>Чтобы показать только публикации со связанным автором, можно использовать метод запроса <code>whereRelation</code>. Для завершения запроса используйте метод <code>get()</code>. Следующий пример выводит публикации, назначенные <code>author</code> со slug <strong>bella-vista</strong>.</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">set</span> authorPosts <span class="token operator">=</span> posts<span class="token punctuation">.</span>whereRelation<span class="token punctuation">(</span><span class="token string"><span class="token punctuation">&#39;</span>author<span class="token punctuation">&#39;</span></span><span class="token punctuation">,</span> <span class="token string"><span class="token punctuation">&#39;</span>slug<span class="token punctuation">&#39;</span></span><span class="token punctuation">,</span> <span class="token string"><span class="token punctuation">&#39;</span>bella-vista<span class="token punctuation">&#39;</span></span><span class="token punctuation">)</span><span class="token punctuation">.</span>get<span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><h3 id="доступ-к-типу-записи"><a href="#доступ-к-типу-записи" class="header-anchor">#</a> Доступ к типу записи</h3><p>Для фильтрации записей по их типу выполните запрос <code>where()</code> по атрибуту <code>content_group</code>. Следующий пример выведет публикации с типом записи <strong>featured_post</strong>.</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">set</span> featuredPosts <span class="token operator">=</span> posts<span class="token punctuation">.</span>where<span class="token punctuation">(</span><span class="token string"><span class="token punctuation">&#39;</span>content_group<span class="token punctuation">&#39;</span></span><span class="token punctuation">,</span> <span class="token string"><span class="token punctuation">&#39;</span>featured_post<span class="token punctuation">&#39;</span></span><span class="token punctuation">)</span><span class="token punctuation">.</span>get<span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><h3 id="пагинация-записеи"><a href="#пагинация-записеи" class="header-anchor">#</a> Пагинация записей</h3><p>Вы также можете применить пагинацию к коллекции с помощью метода <code>paginate()</code>. Следующий пример пагинирует публикации по <strong>10</strong> на страницу и отображает навигацию по страницам.</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">set</span> authorPosts <span class="token operator">=</span> posts<span class="token punctuation">.</span>whereRelation<span class="token punctuation">(</span><span class="token punctuation">.</span><span class="token punctuation">.</span><span class="token punctuation">.</span><span class="token punctuation">)</span><span class="token punctuation">.</span>paginate<span class="token punctuation">(</span><span class="token number">10</span><span class="token punctuation">)</span> <span class="token delimiter punctuation">%}</span></span>

<span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> pager<span class="token punctuation">(</span>authorPosts<span class="token punctuation">)</span> <span class="token delimiter punctuation">}}</span></span>
</code></pre></div><div class="custom-block tip"><p>Обратитесь к <a href="./../features/pagination.html">функции пагинации</a>, чтобы узнать больше о разбиении записей на страницы.</p></div><h3 id="поиск-записеи"><a href="#поиск-записеи" class="header-anchor">#</a> Поиск записей</h3><p>Для поиска записей используйте <a href="./../../extend/database/query.html">метод <code>searchWhere()</code></a> для выполнения поискового запроса по значению столбца. Следующий пример ищет записи по указанному термину и столбцам с использованием регистронезависимого запроса.</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">set</span> foundPages <span class="token operator">=</span> pages<span class="token punctuation">.</span>searchWhere<span class="token punctuation">(</span>searchTerm<span class="token punctuation">,</span> <span class="token punctuation">[</span><span class="token string"><span class="token punctuation">&#39;</span>title<span class="token punctuation">&#39;</span></span><span class="token punctuation">,</span> <span class="token string"><span class="token punctuation">&#39;</span>content<span class="token punctuation">&#39;</span></span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">.</span>get<span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><p>Вы также можете использовать <a href="./../../extend/database/relations.html">метод <code>searchWhereRelation()</code></a> для поиска связанных записей, где имя связи включается в метод для запроса наличия связи.</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">set</span> foundPages <span class="token operator">=</span> pages<span class="token punctuation">.</span>searchWhereRelation<span class="token punctuation">(</span>searchTerm<span class="token punctuation">,</span> <span class="token string"><span class="token punctuation">&#39;</span>author<span class="token punctuation">&#39;</span></span><span class="token punctuation">,</span> <span class="token punctuation">[</span><span class="token string"><span class="token punctuation">&#39;</span>title<span class="token punctuation">&#39;</span></span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">.</span>get<span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><h2 id="жадная-загрузка-связанных-записеи"><a href="#жадная-загрузка-связанных-записеи" class="header-anchor">#</a> Жадная загрузка связанных записей</h2><p>В некоторых случаях, из соображений производительности, вам может потребоваться жадная загрузка связанных записей. Используйте метод <code>load</code> на коллекции, передавая имя связи. В следующем примере связь <code>categories</code> будет загружена с каждой публикацией в коллекции.</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">do</span> authorPosts<span class="token punctuation">.</span>load<span class="token punctuation">(</span><span class="token string"><span class="token punctuation">&#39;</span>categories<span class="token punctuation">&#39;</span></span><span class="token punctuation">)</span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><h2 id="подсчет-записеи"><a href="#подсчет-записеи" class="header-anchor">#</a> Подсчёт записей</h2><p>Допустим, вы хотите отобразить список категорий блога и подсчитать количество публикаций в каждой категории. Сначала определите <a href="./../../element/content/field-entries.html">обратную связь</a> в чертеже категории как <strong>posts</strong>.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">posts</span><span class="token punctuation">:</span>
    <span class="token key atrule">type</span><span class="token punctuation">:</span> entries
    <span class="token key atrule">source</span><span class="token punctuation">:</span> Blog\\Post
    <span class="token key atrule">inverse</span><span class="token punctuation">:</span> categories
    <span class="token key atrule">hidden</span><span class="token punctuation">:</span> <span class="token boolean important">true</span>
</code></pre></div><p>Затем вызовите функцию <code>withCount</code> на компоненте коллекции, затем <code>get</code> для получения коллекции записей категорий. Это создаст атрибут <strong>post_count</strong> на каждой категории.</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">set</span> categories <span class="token operator">=</span> collection<span class="token punctuation">.</span>withCount<span class="token punctuation">(</span><span class="token string"><span class="token punctuation">&#39;</span>posts<span class="token punctuation">&#39;</span></span><span class="token punctuation">)</span><span class="token punctuation">.</span>get<span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token delimiter punctuation">%}</span></span>
<span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">for</span> category <span class="token operator">in</span> categories <span class="token delimiter punctuation">%}</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>h5</span><span class="token punctuation">&gt;</span></span><span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> category<span class="token punctuation">.</span>title <span class="token delimiter punctuation">}}</span></span> (<span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> category<span class="token punctuation">.</span>post_count <span class="token delimiter punctuation">}}</span></span> posts)<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>h5</span><span class="token punctuation">&gt;</span></span>
<span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">endfor</span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><h4 id="см-также"><a href="#см-также" class="header-anchor">#</a> См. также</h4><div class="custom-block also"><ul><li><a href="./../features/pagination.html">Пагинация</a></li><li><a href="./../../extend/database/model.html">Запросы к моделям</a></li><li><a href="./../../extend/database/relations.html">Связи базы данных</a></li></ul></div>`,38))])}const f=p(u,[["render",r]]);export{v as __pageData,f as default};
